-- Generated by tools/tier_spell_scaling.py. Every mismatch count must be zero.
SELECT 'tier_200000_mismatches' AS check_name, COUNT(*) AS result FROM items a JOIN items b ON b.id=a.id-200000 WHERE a.id BETWEEN 200001 AND 399999 AND a.slots>0 AND (a.spelldmg<>IF(b.spelldmg<0,b.spelldmg,ROUND(b.spelldmg*110/100)+IF(b.slots>0 AND b.itemclass=0 AND b.bagslots=0,FLOOR(5*LEAST(100,GREATEST(0,b.hp,b.mana,b.ac,2*GREATEST(b.astr,b.asta,b.adex,b.aagi,b.aint,b.awis,b.acha),IF(b.itemtype IN (0,1,2,3,4,5,7,19,35,45) AND b.delay>0,FLOOR(100*GREATEST(0,b.damage)/NULLIF(b.delay,0)),0)))/100),0)) OR a.healamt<>IF(b.healamt<0,b.healamt,ROUND(b.healamt*110/100)+IF(b.slots>0 AND b.itemclass=0 AND b.bagslots=0,FLOOR(5*LEAST(100,GREATEST(0,b.hp,b.mana,b.ac,2*GREATEST(b.astr,b.asta,b.adex,b.aagi,b.aint,b.awis,b.acha),IF(b.itemtype IN (0,1,2,3,4,5,7,19,35,45) AND b.delay>0,FLOOR(100*GREATEST(0,b.damage)/NULLIF(b.delay,0)),0)))/100),0)));
